from lib import *
S = SS('g45')
steps = [
    step("九个小函数各调用 100 次:七种泄漏(leakSend 往无人接收的局部 channel 发送、leakRecv 从无人发送的局部 channel 接收、leakNil 从 nil channel 接收、leakMutex 再次 Lock 一个已被锁住且没人解锁的 Mutex、leakWG 等一个永远不会 Done 的 WaitGroup、leakSelect 执行空的 select{}、blockedGlobal 从一个全局 channel 接收)和两种修好的写法(fixedBuffered 给 channel 留 1 个缓冲、fixedCtx 用 context.WithCancel 让 select 有退出路径)。起始 NumGoroutine = 1,调用之后是 701 = 1 + 7 × 100:两种修好的写法没有留下任何 goroutine,七种泄漏各留下 100 个。", t=tl(S(1)), mark=lidx(S(1), 'NumGoroutine = 701'), b=bars([['起始', 1, '1'], ['7 种泄漏 × 100 之后', 701, '701']], 701, done=[0], mark=[1]), kv=KV([['七种泄漏', '各 100 个 goroutine 永远阻塞'], ['fixedBuffered / fixedCtx', '0 个留下'], ['NumGoroutine', '1 → 701']], ['七种泄漏'])),
    step("goroutine profile(debug=1)按栈聚合,直接告诉你卡在哪一行:100 个 @ main.blockedGlobal.func1 main.go:25;100 个 @ main.leakMutex.func1 main.go:22;100 个 @ main.leakNil.func1 main.go:21;100 个 @ main.leakRecv.func1 main.go:20;100 个 @ main.leakSelect.func1 main.go:24;100 个 @ main.leakSend.func1 main.go:19;100 个 @ main.leakWG.func1 main.go:23;另有 1 个是正在写 profile 的 main。每一组都带完整的栈,最后一行用户代码就是 goroutine 阻塞的位置。", t=tl(S(2)), done=lidx(S(2), 'goroutine profile(701'), mark=lidx(S(2), 'main.leakSend.func1', 'main.leakNil.func1', 'main.leakMutex.func1', 'main.blockedGlobal'), kv=KV([['聚合方式', '相同栈的 goroutine 合成一行,前面是个数'], ['定位', '栈里最后的用户代码行:main.go:19–25'], ['注意', 'blockedGlobal 这种等全局 channel 的 goroutine 也在列表里']], ['定位'])),
    step("debug=2 的完整转储里每个 goroutine 的等待原因:[chan receive] 200 个(leakRecv 与 blockedGlobal)、[chan receive (nil chan)] 100 个、[chan send] 100 个、[select (no cases)] 100 个、[sync.Mutex.Lock] 100 个、[sync.WaitGroup.Wait] 100 个、[running] 1 个。等待原因直接指明了是哪一类阻塞。", t=tl(S(3)), done=lidx(S(3), '[chan receive]', '[chan send]'), mark=lidx(S(3), '[chan receive (nil chan)]', '[select (no cases)]', '[sync.Mutex.Lock]', '[sync.WaitGroup.Wait]'), kv=KV([['[chan send] / [chan receive]', '有人没接收 / 没发送'], ['[chan receive (nil chan)]', '在 nil channel 上等待'], ['[select (no cases)]', '空 select'], ['[sync.Mutex.Lock] / [sync.WaitGroup.Wait]', '锁与等待组']], ['[chan receive (nil chan)]'])),
    step("goroutineleak profile(Go 1.27.1 的 pprof 里有这个 profile,写它之前会先做一次带泄漏检测的 GC):找出 598 个泄漏的 goroutine:leakNil 100、leakRecv 100、leakSelect 100、leakSend 100、leakWG 100、leakMutex 98。blockedGlobal 没有被报告(它等的 channel 是全局变量,仍然可达);leakMutex 少了 2 个,我没有查明原因。生成这个 profile 耗时 2.8 ms。", t=tl(S(4)), done=lidx(S(4), 'goroutineleak profile(598', 'main.leakNil'), mark=lidx(S(4), 'main.leakMutex', '生成 goroutineleak profile'), b=bars([['goroutine profile 总数', 701, '701'], ['goroutineleak 报告', 598, '598'], ['blockedGlobal(可达,不报)', 100, '100']], 701, done=[0], mark=[1, 2]), kv=KV([['报告的泄漏', '598 个(七种写法里除 blockedGlobal 之外的六种)'], ['没报告的', 'blockedGlobal:等的 channel 可达'], ['成本', '生成一次 2.8 ms']], ['没报告的'])),
]
A = mkartg('g45', 45, 'Go,goroutine,泄漏,pprof,goroutineleak,真实验证,动画演示',
    '用 Go 1.27.1 复现七种 goroutine 泄漏(发送无人接收、接收无人发送、nil channel、重复 Lock、WaitGroup 永不 Done、空 select、等全局 channel)各 100 个,NumGoroutine 从 1 变成 701;goroutine profile(debug=1)把它们聚合到 main.go 的具体行,debug=2 给出每个的等待原因;Go 1.27.1 新增的 goroutineleak profile 通过 GC 报告其中 598 个(等全局 channel 的不报);两种修好的写法(缓冲 channel、context 取消)不留下 goroutine。',
    'goroutine 泄漏是 Go 服务里最常见的内存增长原因之一:一个 goroutine 永远等不到它等的事。这篇用七种典型的泄漏写法复现,再用 goroutine profile 定位到具体的行、用等待原因判断类别,并用 Go 1.27.1 里新出现的 goroutineleak profile 让 GC 帮你找出真正的泄漏。',
    [('701', '七种泄漏各 100 个之后的 NumGoroutine(起始 1,两种修好的写法没有留下 goroutine)'), ('main.go:19', 'goroutine profile 直接给出每组泄漏 goroutine 阻塞的源码行'), ('598 个', 'goroutineleak profile 报告的泄漏数(700 个阻塞的 goroutine 里,等全局 channel 的 100 个不算)')],
    [('复现与现象', '<p>泄漏的共同点是:goroutine 在等一个再也不会发生的事件。<code>runtime.NumGoroutine()</code> 持续增长是最直接的信号;每个泄漏的 goroutine 约占 2.8 KB(见上一篇),十万个就是 280 MB。两种修好的写法不留任何 goroutine:给 channel 一个缓冲,或让 <code>select</code> 同时等一个能取消的 <code>context</code>。</p>'),
     ('goroutine profile 定位', '<p>goroutine profile 把栈相同的 goroutine 合并并给出个数。<code>debug=1</code> 输出里每个栈的最下面一行用户代码就是它阻塞的位置(<code>main.go:19</code> 到 <code>main.go:25</code>)。可以通过 <code>net/http/pprof</code> 的 <code>/debug/pprof/goroutine?debug=1</code> 在线上抓,本文没有试。</p>'),
     ('等待原因', '<p><code>debug=2</code> 的完整转储里,每个 goroutine 的标题带着等待原因,例如 <code>[chan send]</code>、<code>[chan receive (nil chan)]</code>、<code>[select (no cases)]</code>、<code>[sync.Mutex.Lock]</code>。这些词本身就能告诉你是哪类问题:nil channel 通常是忘了初始化,空 select 是写错了,等锁是忘了解锁。</p>'),
     ('goroutineleak profile', '<p>Go 1.27.1 的 <code>runtime/pprof</code> 里多了 <code>goroutineleak</code> profile,源码注释把它描述为“stack traces of all leaked goroutines”,写出它之前先运行一次带泄漏检测的 GC。从实验看,它报告的是“等待的同步对象已经没有其它可达引用”的那些:等全局 channel 的 100 个没有报告,因为全局变量还指着那个 channel(这正是它不会误报的原因,也是它的盲区)。检测的具体算法我没有读源码,这里只是实测的行为。leakMutex 少报告了 2 个,原因没查明。</p>')],
    steps,
    [ENV_G + '。每种写法调用 100 次;profile 用 runtime/pprof 在进程内取得并解析(debug=1 的文本按栈聚合、debug=2 的标题行统计等待原因);为避免内联改变栈,编译时加了 -gcflags=-l;goroutineleak 是 Go 1.27.1 的 pprof.Profiles() 里列出的 profile,源码里的描述见 runtime/pprof/pprof.go',
     '没有验证:goroutineleak profile 的检测算法与误报漏报边界(只验证了七种写法)、在线上通过 net/http/pprof 抓取、泄漏的 goroutine 持有的内存与 channel 缓冲对堆的影响、goleak 一类测试库的用法、时间驱动的泄漏(如忘了 Stop 的 Ticker)是否被 profile 报告'],
    'goroutine 泄漏')
